head.script:
var nppfsObj = {};
nppfsObj.npPfsStartup = function(formId, firewall) {
//jQuery(document).ready(function(){	
	/*
	npPfsStartup(document.form1, false, true, true, "enc", "on");
	1. form 양식 : 기본값 DOM Document 상의 첫번째 form
	2. 개인방화벽 사용여부 : 기본값 false
	3. 키보드보안 사용여부 : 기본값 false
	4. 단말정보수집 사용여부 : 기본값 false
	5. 키보드보안 E2E 필드 설정 속성명 : 기본값 "enc"
	6. 키보드보안 E2E 필드 설정 속성값: 기본값 "on"
	부가적인 설정은(예, 설치확인 등) /pluginfree/js/nppfs-1.13.0.js를 수정하여 설정하십시오.
*/
/*
	npPfsStartup(
		document.form2
		, true
		, true
		, true
		, "npkencrypt"
		, "on"
	);
*/
	//URL Rewriting : Cookie가 허용되지 않는 브라우저에서는 다음 구문을 추가하여 쿠키없이도 동작이 가능하도록 처리
	uV.dV.Gf = "/pluginfree/nos/jsp/nppfs.key.jsp";    // 키발급 경로
	uV.dV.zf = "/pluginfree/nos/jsp/nppfs.remove.jsp"; // 키삭제 경로
	uV.dV.zo = "/pluginfree/nos/jsp/nppfs.keypad.jsp";  // 마우스입력기 페이지
	uV.dV.eP = "/pluginfree/nos/jsp/nppfs.ready.jsp";  // 초기화상태 확인경로 
	uV.dV.Fz = "/websquare/websquare.jsp?w2xPath=/jsp/ibankMng/securityCenter/programSetupInfo.xml&P_name=NOS"; // 설치안내 페이지

	if(firewall) { // 개인방화벽만 사용
		//20161031 금보원 취약점 진단 조치 - 김창석
		//npPfsStartup("#"+formId, true, false, false, false, "npkencrypt", "on");
		npPfsStartup("#"+formId, true, true, false, true, "npkencrypt", "on");
	} else { // 개인방화벽, e2e 사용
		npPfsStartup("#"+formId, true, true, false, true, "npkencrypt", "on");
	}


//});
};


var _mode           = "REAL";
console.log(_mode);
var _isLogin        =  false;
var _ibank          = "";
var _custLevel      = "";
var _myPage         = "";
var _stock          = "";
var _sunshine       = "";
var _kind           = "";
var _dupLogin       = "false";
var _externalAccess = "false";
var _pwdChngDt		= "";

/* 20190725 웹취약점 (XSS) - 김창석i START */
var _xssCheck 		= "false";
/* 20190725 웹취약점 (XSS) - 김창석i END */

/* 20191108 웹취약점 조치(1-1. 간편한도조회 인증결과변조) - 김창석i START */
var _authCheck 		= "false";

var bypassFlag = "true";
/* 20191108 웹취약점 조치(1-1. 간편한도조회 인증결과변조) - 김창석i END */

			requires("uiplugin.popup");

			window.onload = init;

			function init() {

                var userAgent = navigator.userAgent.toLocaleLowerCase();
				var previousUrl = document.referrer;
				var nowUrl = window.location.href;
			    if(userAgent.match("ios") || userAgent.match("iphone") || userAgent.match("ipad") || userAgent.match("android")) {
			        if(previousUrl.indexOf("m.kbsavings.com") == -1) {
			    		if(nowUrl.indexOf("consumerMain") > -1){
			    			location.replace("https://m.kbsavings.com/mobweb/kiwiintro/guide_brnc_info.do");	
			    		}else if(nowUrl.indexOf("landing.xml") > -1 || nowUrl.indexOf("easyLimit_01.xml") > -1 || nowUrl.indexOf("kindLoanMain.xml") > -1){
			    			location.replace("https://m.kbsavings.com/mobweb/kiwiLoanBridgeExt.do");
			    		}else if(nowUrl.indexOf("depositItemInfoMain") > -1){
			    			location.replace("https://m.kbsavings.com/mobweb/kiwisavings/kiwiRotarySavings2Prod.do");
			    		}else if(nowUrl.indexOf("loanItemInfoMain") > -1){
			    			location.replace("https://m.kbsavings.com/mobweb/kiwiloan/LON100000M.do");
			    		}else if(nowUrl.indexOf("branchInfo.xml") > -1) {
			    			location.replace("https://m.kbsavings.com/mobweb/kiwiintro/guide_brnc_info.do");
			    		}else if(nowUrl.indexOf("ibankMain.xml") > -1) {
			    			location.replace("https://m.kbsavings.com/mobweb/main.do");
			    		}else if(nowUrl.indexOf("loanItemInfo.xml&ITEM_CODE=IL66") > -1) {
			    			location.replace("https://m.kbsavings.com/mobweb/kiwiloan/LON400010M.do?lonGdsNo=971&entryType=02");
			    		}else if(nowUrl.indexOf("depositItemInfo.xml&ITEM_CODE=IB16") > -1) {
			    			location.replace("https://m.kbsavings.com/mobweb/kiwisavings/liivSavingsProd2.do");
			    		}
			    	}
			    }

				try{
					WebSquare.startApplication();

					if( bypassFlag == "true"){
					}else{
						alert("시스템 업그레이드 작업중입니다");
						location.href="www.kbsavings.com/404.html";
						//var param = {"ERR_CODE":"9999","ERR_MSG":"시스템 업그레이드 작업중입니다."}; 
						//$w.url("/jsp/common/page/errorPage.xml", {param:param});
					}	

				} catch(e) {
					alert(e.message);
				}
			}
			if ( _dupLogin == "true" ) {
				var param = {"ERR_GNB":"/www.kbsavings.com/"};       
				$w.url("/jsp/common/page/dupErrorPage.xml", {param:param}); // 에러페이지로 이동
			}

			// 외부 접속시 메인 페이지로 이동
			if ( _externalAccess == "true" ) {
				$w.url("/"); // 메인페이지로 이동
			}

			/* 20190725 웹취약점 (XSS) - 김창석i START */
			if ( _xssCheck == "true" ) {
				var param = {"ERR_CODE":"","ERR_MSG":"비정상적인 접근입니다."}; 
				$w.url("/jsp/common/page/errorPage.xml", {param:param});
			}
			/* 20190725 웹취약점 (XSS) - 김창석i END */

			/* 20191108 웹취약점 조치(1-1. 간편한도조회 인증결과변조) - 김창석i START */
			if ( _authCheck == "true" ) {
				var param = {"ERR_CODE":"9999","ERR_MSG":"비정상적인 접근입니다."}; 
				$w.url("/jsp/common/page/errorPage.xml", {param:param});
			}
			/* 20191108 웹취약점 조치(1-1. 간편한도조회 인증결과변조) - 김창석i END */

// 이엠넷 통계
